import{_ as p,a0 as l,w as o,s as r,I as n,x as t,a1 as a,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何使用 Awk 打印文件中的字段和列 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Awk 打印文件中的字段和列 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Awk 打印文件中的字段和列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Awk 打印文件中的字段和列 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160425 How to Use Awk to Print Fields and Columns in File","title":"如何使用 Awk 打印文件中的字段和列","tag":"201607","desc":""},"relativePath":"201607/20160425 How to Use Awk to Print Fields and Columns in File.md","filePath":"[post].md"}'),u={name:"201607/20160425 How to Use Awk to Print Fields and Columns in File.md"};function k(m,s,h,g,w,c){const i=l("Link");return o(),r("div",null,[s[19]||(s[19]=n("h1",{id:"如何使用-awk-打印文件中的字段和列",tabindex:"-1"},[t("如何使用 Awk 打印文件中的字段和列 "),n("a",{class:"header-anchor",href:"#如何使用-awk-打印文件中的字段和列","aria-label":"Permalink to “如何使用 Awk 打印文件中的字段和列”"},"​")],-1)),n("p",null,[s[1]||(s[1]=t("在 ",-1)),a(i,{href:"http://www.tecmint.com/tag/awk-command/"},{default:e(()=>[...s[0]||(s[0]=[t("Linux Awk 命令系列介紹",-1)])]),_:1}),s[2]||(s[2]=t(" 的這部分，我們來看一下 awk 最重要的功能之一，字段編輯。",-1))]),s[20]||(s[20]=n("p",null,"首先我們要知道 Awk 會自動把輸入的行切分為字段，字段可以定義為是一些字符集，這些字符集和其它字段被內部字段分隔符分離。",-1)),s[21]||(s[21]=n("p",null,[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2016/04/Awk-Print-Fields-and-Columns.png",alt:""})],-1)),s[22]||(s[22]=n("blockquote",null,[n("p",null,"Awk 輸出字段和列")],-1)),n("p",null,[s[4]||(s[4]=t("如果你熟悉 Unix/Linux 或者懂得 ",-1)),a(i,{href:"http://www.tecmint.com/category/bash-shell/"},{default:e(()=>[...s[3]||(s[3]=[t("bash shell 編程",-1)])]),_:1}),s[5]||(s[5]=t("，那麼你也應該知道內部字段分隔符（IFS）變量。Awk 默認的 IFS 是 tab 和空格。",-1))]),s[23]||(s[23]=d(`<p>Awk 字段切分的工作原理如下：當獲得一行輸入時，根據定義的 IFS，第一個字符集是字段一，用 $1 表示，第二個字符集是字段二，用 $2 表示，第三個字符集是字段三，用 $3 表示，以此類推直到最後一個字符集。</p><p>為了更好的理解 Awk 的字段編輯，讓我們來看看下面的例子：</p><p><strong>事例 1:</strong>： 我創建了一個名為 tecmintinfo.txt 的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi tecmintinfo.txt</span></span>
<span class="line"><span># cat tecmintinfo.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Create-File-in-Linux.png" alt=""></p><blockquote><p>在 Linux 中創建文件</p></blockquote><p>然後在命令列中使用以下命令打印 tecmintinfo.txt 文件中的第一、第二和第三個字段。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $1 $2 $3 }&#39; tecmintinfo.txt</span></span>
<span class="line"><span>TecMint.comisthe</span></span></code></pre></div><p>從上面的輸出中你可以看到，三個字段中的第一個是按照定義的 IFS，也就是空格，打印的。</p><ul><li>字段一 “TecMint.com” 使用 $1 訪問。</li><li>字段二 “is” 通過 $2 訪問。</li><li>字段三 “the” 通過 $3 訪問。</li></ul><p>如果你注意打印的輸出，可以看到字段值之間並沒有分隔開，這是 print 默認的方式。</p><p>為了在字段值之間加入空格，你需要像下面這樣添加（,）分隔符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $1, $2, $3; }&#39; tecmintinfo.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TecMint.com is the</span></span></code></pre></div><p>很重要而且必須牢記的一點是，Awk 中 （$） 的使用和在 shell 腳本中不一樣。</p><p>在 shell 腳本中 （$） 用於獲取變量的值，而在 Awk 中 （$） 只用於獲取一個字段的內容，而不能用於獲取變量的值。</p><p><strong>事例2</strong>： 讓我們再看一個使用多行文件 my_shoping.list 的例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>No	Item_Name		Unit_Price	Quantity	Price</span></span>
<span class="line"><span>1	Mouse			#20,000		   1		#20,000</span></span>
<span class="line"><span>2 	Monitor			#500,000	   1		#500,000</span></span>
<span class="line"><span>3	RAM_Chips		#150,000	   2		#300,000</span></span>
<span class="line"><span>4	Ethernet_Cables	        #30,000		   4		#120,000</span></span></code></pre></div><p>假設你只想打印購物清單中每個物品的 Unit_Price，你需要允許下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name Unit_Price</span></span>
<span class="line"><span>Mouse #20,000</span></span>
<span class="line"><span>Monitor #500,000</span></span>
<span class="line"><span>RAM_Chips #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><p>Awk 也有一個 printf 命令，它能幫助你用更好的方式格式化輸出，正如你可以看到上面的輸出並不清晰。</p><p>使用 printf 格式化輸出 Item_Name 和 Unit_Price：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{printf &quot;%-10s %s\\n&quot;,$2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name  Unit_Price</span></span>
<span class="line"><span>Mouse      #20,000</span></span>
<span class="line"><span>Monitor    #500,000</span></span>
<span class="line"><span>RAM_Chips  #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>使用 Awk 進行文本和字符串過濾時字段編輯功能非常重要，它能幫助你從列表中獲取列的特定數據。同時需要記住 Awk 中 （$） 操作符和 shell 腳本中不一樣。</p><p>我希望這篇文章能對你有所幫助，如果你需要獲取其它信息或者有任何疑問，都可以在下面的評論框中告訴我們。</p><hr>`,26)),n("p",null,[s[7]||(s[7]=t("via: ",-1)),a(i,{href:"http://www.tecmint.com/awk-print-fields-columns-with-space-separator/?utm_source=feedburner&utm_medium=feed&utm_campaign=Feed%3A+tecmint+%28Tecmint%3A+Linux+Howto%27s+Guide%29"},{default:e(()=>[...s[6]||(s[6]=[t("http://www.tecmint.com/awk-print-fields-columns-with-space-separator/?utm_source=feedburner&utm_medium=feed&utm_campaign=Feed%3A+tecmint+(Tecmint%3A+Linux+Howto's+Guide)",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=t("作者：",-1)),a(i,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...s[8]||(s[8]=[t("Aaron Kili",-1)])]),_:1}),s[12]||(s[12]=t(" 譯者：",-1)),a(i,{href:"https://github.com/ictlyh"},{default:e(()=>[...s[9]||(s[9]=[t("ictlyh",-1)])]),_:1}),s[13]||(s[13]=t(" 校對：",-1)),a(i,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:e(()=>[...s[10]||(s[10]=[t("校對者ID",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[t("LCTT",-1)])]),_:1}),s[17]||(s[17]=t(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[t("Linux中國",-1)])]),_:1}),s[18]||(s[18]=t(" 榮譽推出",-1))])])}const A=p(u,[["render",k]]);export{C as __pageData,A as default};
